import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int c = in.nextInt();
        System.out.println((int) Math.ceil((double) n / c));
    }
}

solution.cpp:
#include <iostream>
#include <cmath>
using namespace std;

int main() {
    int n, c;
    cin >> n >> c;
    cout << (int) ceil((double) n / c) << endl;
    return 0;
}
